-- Real PostgreSQL/RLS tests. All fixtures and attempted writes roll back.
begin;
create temporary table fs_context(k text primary key,v text) on commit drop;
insert into fs_context select k,gen_random_uuid()::text from unnest(array['oa','ob','ua','u2','u3','ub','ea','eb','wa','w2','w3','wb','report','skill']) k;
create temporary table fs_results(name text) on commit drop;
grant select on fs_context to authenticated;
grant select,insert on fs_results to authenticated;
do $$ begin execute format('grant usage on schema %I to authenticated',pg_my_temp_schema()::regnamespace); end $$;
create function pg_temp.expect(v boolean,label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'Security assertion failed: %',label; end if; insert into pg_temp.fs_results values(label); end $$;
create function pg_temp.denied(stmt text,label text) returns void language plpgsql as $$ declare n integer; begin begin execute stmt; get diagnostics n=row_count; if n<>0 then raise exception 'Unauthorized write succeeded: %',label; end if; exception when insufficient_privilege or check_violation then null; end; insert into pg_temp.fs_results values(label); end $$;
grant execute on function pg_temp.expect(boolean,text),pg_temp.denied(text,text) to authenticated;
insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data) select v::uuid,'qa-'||v||'@example.test','{}','{}' from fs_context where k in('ua','u2','u3','ub','ea','eb');
insert into public.organizations(id,name,industry,settings) select v,'Disposable RLS fixture','Test','{"standardDailyHours":8,"overtimeMultiplier":1.5,"maxDailyHoursThreshold":10,"minRestHoursThreshold":11,"maxWeeklyHoursThreshold":48}' from fs_context where k in('oa','ob');
insert into public.organization_memberships(user_id,org_id,role) select u.v::uuid,o.v,case when u.k in('ea','eb') then 'employer' else 'worker' end from fs_context u join fs_context o on o.k=case when u.k in('ub','eb') then 'ob' else 'oa' end where u.k in('ua','u2','u3','ub','ea','eb');
insert into public.workers(id,org_id,user_id,name,role,hourly_rate) select w.v,o.v,u.v::uuid,'Disposable worker','Fixture',130 from fs_context w join fs_context u on u.k=case w.k when 'wa' then 'ua' when 'w2' then 'u2' when 'w3' then 'u3' else 'ub' end join fs_context o on o.k=case when w.k='wb' then 'ob' else 'oa' end where w.k in('wa','w2','w3','wb');
insert into public.safety_reports(id,org_id,worker_id,category,severity,title,description) select r.v,o.v,w.v,'SAFETY_HAZARD','LOW','Disposable test','Rollback only' from fs_context r,fs_context o,fs_context w where r.k='report' and o.k='oa' and w.k='w2';
insert into public.skill_passport_entries(id,org_id,worker_id,skill,industry,proficiency) select s.v::uuid,o.v,w.v,'Disposable competency','Test','Intermediate' from fs_context s,fs_context o,fs_context w where s.k='skill' and o.k='oa' and w.k='w2';
insert into public.worker_feedback(worker_id,org_id,environment,fairness,safety,communication,satisfaction,comment) select w.v,o.v,4,4,4,4,4,'Not exposed to employers' from fs_context w,fs_context o where w.k in('wa','w2') and o.k='oa';
do $$
declare oa text; ob text; ua text; ub text; ea text; eb text; u3 text; wa text; wb text; w2 text; w3 text; report text; skill text; s public.shifts; result jsonb;
begin
 select v into oa from pg_temp.fs_context where k='oa'; select v into ob from pg_temp.fs_context where k='ob';
 select v into ua from pg_temp.fs_context where k='ua'; select v into ub from pg_temp.fs_context where k='ub'; select v into ea from pg_temp.fs_context where k='ea'; select v into eb from pg_temp.fs_context where k='eb'; select v into u3 from pg_temp.fs_context where k='u3';
 select v into wa from pg_temp.fs_context where k='wa'; select v into wb from pg_temp.fs_context where k='wb'; select v into w2 from pg_temp.fs_context where k='w2'; select v into w3 from pg_temp.fs_context where k='w3'; select v into report from pg_temp.fs_context where k='report'; select v into skill from pg_temp.fs_context where k='skill';
 perform set_config('request.jwt.claim.sub',ua,true); perform set_config('role','authenticated',true);
 perform pg_temp.expect((select count(*)=1 from public.workers where org_id=oa),'Worker sees only own records');
 perform pg_temp.expect((select count(*)=0 from public.workers where id=w2 or org_id=ob),'Cross-worker and cross-organization reads denied');
 perform pg_temp.denied(format('update public.organization_memberships set role=''admin'' where user_id=%L',ua),'Self promotion denied');
 perform pg_temp.denied(format('update public.workers set hourly_rate=1 where id=%L',wa),'Wage tampering denied');
 perform pg_temp.denied(format('update public.organizations set settings=''{}'' where id=%L',oa),'Overtime policy tampering denied');
 perform pg_temp.denied(format('insert into public.shifts(org_id,worker_id,hourly_rate,standard_hours,overtime_multiplier) values(%L,%L,1,8,1.5)',oa,wa),'Forged shifts denied');
 perform pg_temp.denied(format('update public.safety_reports set status=''RESOLVED'' where id=%L',report),'Unauthorized grievance resolution denied');
 perform pg_temp.denied(format('update public.safety_reports set worker_id=%L where id=%L',wa,report),'Report ownership changes denied');
 perform pg_temp.denied(format('update public.safety_reports set resolved_by=%L where id=%L',ua,report),'Audit metadata changes denied');
 perform pg_temp.denied(format('update public.skill_passport_entries set skill=''Forged'' where id=%L',skill),'Other worker skill edits denied');
 perform pg_temp.denied(format('delete from public.worker_feedback where worker_id=%L',wa),'Worker feedback deletion denied');
 begin perform public.fairshift_check_in(ob); raise exception 'Cross-org RPC allowed'; exception when insufficient_privilege then insert into pg_temp.fs_results values('Cross-organization shift RPC denied'); end;
 s:=public.fairshift_check_in(oa); perform pg_temp.expect(s.worker_id=wa and s.hourly_rate=130,'Server binds shift owner and wage');
 begin perform public.fairshift_check_in(oa); raise exception 'Duplicate shift allowed'; exception when unique_violation then insert into pg_temp.fs_results values('Duplicate active shift prevented'); end;
 s:=public.fairshift_check_out(oa); perform pg_temp.expect(s.end_time is not null and s.total_estimated_earnings=s.regular_pay+s.overtime_pay,'Server checkout calculates consistent totals');
 perform set_config('request.jwt.claim.sub',ea,true);
 perform pg_temp.expect((select count(*)=3 from public.workers where org_id=oa),'Employer reads assigned organization');
 perform pg_temp.expect((select count(*)=0 from public.workers where org_id=ob),'Employer cross-organization reads denied');
 perform pg_temp.expect((select count(*)=0 from public.worker_feedback where org_id=oa),'Employer cannot read raw feedback');
 result:=public.fairshift_feedback_summary(oa); perform pg_temp.expect((result->>'suppressed')::boolean,'Two contributors are suppressed');
 begin perform public.fairshift_feedback_summary(ob); raise exception 'Foreign feedback exposed'; exception when insufficient_privilege then insert into pg_temp.fs_results values('Foreign feedback summary denied'); end;
 update public.safety_reports set status='RESOLVED',resolution_note='Rollback test' where id=report;
 perform pg_temp.expect((select resolved_by=ea::uuid and resolved_at is not null from public.safety_reports where id=report),'Employer resolution is audited');
 perform set_config('request.jwt.claim.sub',eb,true);
 perform pg_temp.denied(format('update public.safety_reports set status=''OPEN'' where id=%L',report),'Other employer cannot modify organization A report');
 perform set_config('request.jwt.claim.sub',u3,true);
 insert into public.worker_feedback(worker_id,org_id,environment,fairness,safety,communication,satisfaction) values(w3,oa,2,2,2,2,2);
 perform set_config('request.jwt.claim.sub',ea,true);
 result:=public.fairshift_feedback_summary(oa); perform pg_temp.expect(not (result->>'suppressed')::boolean and (result->>'responses')::integer=3 and not(result?'worker_id') and not(result?'comment'),'Three contributors produce identity-free aggregate');
 perform set_config('role','none',true);
end $$;
select count(*) as passed_assertions from fs_results;
rollback;
select 'All 23 PostgreSQL assertions completed; disposable fixtures rolled back.' as verification;